function openForm(kind,record=null,prefill=''){currentModal={kind,record};const submitButton=document.getElementById('recordForm').querySelector('[type=\"submit\"]');if(submitButton){submitButton.disabled=false;submitButton.innerHTML='Salvar registro <span>→</span>'}const cfg=forms[kind];document.getElementById('modalTitle').textContent=record?`Editar ${cfg.title.replace(/^Nova /,'').toLowerCase()}`:cfg.title;document.getElementById('modalEyebrow').textContent=cfg.eyebrow;const form=document.getElementById('formFields');form.innerHTML=cfg.fields.map(f=>fieldHTML(f,record,prefill)).join('');wireEntryForm(form);document.getElementById('modalBackdrop').classList.add('open');document.getElementById('modalBackdrop').setAttribute('aria-hidden','false');setTimeout(()=>form.querySelector('input,select,textarea')?.focus(),50)}
function wireEntryForm(form){const type=form.querySelector('[name="type"]');if(!type)return;const status=form.querySelector('[name="status"]');const expected=form.querySelector('[name="expectedReturn"]')?.closest('.field');const update=()=>{const options={Receita:['Recebido','Previsto','Cancelado'],Custo:['Pago','Previsto','Cancelado'],Investimento:['Planejado','Aprovado','Realizado','Cancelado']}[type.value]||['Recebido'];if(status){const previous=status.value;status.innerHTML=options.map(x=>`<option>${x}</option>`).join('');status.value=options.includes(previous)?previous:options[0]}expected?.classList.toggle('hidden',type.value!=='Investimento')};type.addEventListener('change',update);update()}
function fieldHTML(f,rec,prefill){const [key,label,type,opts,extra]=f;let val=rec?.[key]??(key==='month'?(prefill||monthKey()):key==='created'?new Date().toISOString().slice(0,10):key==='date'?(currentModal?.kind==='entry'?(financeMonth===monthKey()?new Date().toISOString().slice(0,10):`${financeMonth}-01`):new Date().toISOString().slice(0,10)):key==='status'?({task:'Não iniciada',team:'Ativo',ticket:'Novo',contact:'Novo',campaign:'Planejada',expense:'Ativa',post:'Rascunho',entry:'Recebido'}[currentModal?.kind]||''):key==='type'&&prefill?prefill:key==='category'&&prefill?prefill:'');let cls=extra?.includes('full')?' full':'';let req=extra?.includes('required')?'required':'';let input='';if(type==='select')input=`<select name="${key}" ${req}>${opts.map(o=>`<option ${val===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else if(type==='textarea')input=`<textarea name="${key}" placeholder="${esc(opts||'')}" ${req}>${esc(val)}</textarea>`;else if(type==='file')input=`<input name="${key}" type="file" accept="image/*" ${rec?.cover?'':'required'}/><small class="file-help">${rec?.cover?'Imagem atual mantida se você não escolher outra. ':''}${esc(opts||'')}</small>`;else input=`<input name="${key}" type="${type}" value="${esc(val)}" ${req} ${type==='number'?'min="0" step="0.01"':''} placeholder="${type==='number'?'0':esc(opts||'')}" />`;return `<div class="field${cls}"><label for="f_${key}">${label}</label>${input}</div>`}
function closeForm(){document.getElementById('modalBackdrop').classList.remove('open');document.getElementById('modalBackdrop').setAttribute('aria-hidden','true');currentModal=null}
function wireView(){document.querySelectorAll('#content [data-view]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.openTab)peopleTab=b.dataset.openTab;setView(b.dataset.view)}));document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>openForm(b.dataset.add,null,b.dataset.type||b.dataset.prefill||b.dataset.month||'')));document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.edit;const record=kind==='finance'?db.finance.find(x=>(x.id||x.month)===b.dataset.id):db[kind].find(x=>x.id===b.dataset.id);if(record)openForm(kind==='financeEntries'?'entry':({tasks:'task',team:'team',tickets:'ticket',contacts:'contact',campaigns:'campaign',posts:'post',expenses:'expense',finance:'finance'})[kind],record)}));document.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>removeRecord(b.dataset.delete,b.dataset.id)));document.querySelectorAll('[data-status]').forEach(s=>s.addEventListener('change',()=>{const obj=db[s.dataset.status].find(x=>x.id===s.dataset.id);if(obj){obj.status=s.value;persist();toast('Status atualizado')}}));document.querySelectorAll('[data-people-tab]').forEach(b=>b.addEventListener('click',()=>{peopleTab=b.dataset.peopleTab;render()}));document.querySelectorAll('[data-preview]').forEach(b=>b.addEventListener('click',()=>{contentPreviewMode=b.dataset.preview;render()}));document.querySelectorAll('[data-scroll-target]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.scrollTarget)?.scrollIntoView({behavior:'smooth',block:'start'})));document.querySelectorAll('[data-ai-cost]').forEach(input=>input.addEventListener('change',()=>{const key=input.dataset.aiCost;db.aiCostPlan={...newState().aiCostPlan,...db.aiCostPlan,[key]:Math.max(0,Number(input.value)||0)};persist();toast('Estimativa atualizada')}));let dragId=null;document.querySelectorAll('[data-post-tile]').forEach(tile=>tile.addEventListener('dragstart',e=>{dragId=tile.dataset.postTile;e.dataTransfer.setData('text/plain',dragId)}));document.querySelectorAll('.feed-tile').forEach(tile=>{tile.addEventListener('dragover',e=>e.preventDefault());tile.addEventListener('drop',e=>{e.preventDefault();const moving=dragId||e.dataTransfer.getData('text/plain');if(!moving)return;const targetId=tile.dataset.postTile;const list=db.posts.slice().sort((a,b)=>(a.order??0)-(b.order??0));const from=list.findIndex(x=>x.id===moving);let to=targetId?list.findIndex(x=>x.id===targetId):Number(tile.dataset.slot);if(from<0||to<0)return;const [item]=list.splice(from,1);list.splice(Math.min(to,list.length),0,item);list.forEach((p,i)=>p.order=i);db.posts=list;persist();toast('Ordem do feed atualizada')})});}
function removeRecord(kind,key){if(!confirm('Excluir este registro?'))return;if(kind==='finance')db.finance=db.finance.filter(x=>(x.id||x.month)!==key);else db[kind]=db[kind].filter(x=>x.id!==key);persist();toast('Registro excluído')}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>t.classList.remove('show'),2400)}
document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.openTab)peopleTab=b.dataset.openTab;setView(b.dataset.view)}));
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('closeModal').addEventListener('click',closeForm);document.getElementById('cancelModal').addEventListener('click',closeForm);document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeForm()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeForm()});
document.getElementById('recordForm').addEventListener('submit',async e=>{e.preventDefault();if(!currentModal)return;const submitButton=e.currentTarget.querySelector('[type="submit"]');submitButton.disabled=true;submitButton.textContent='Salvando…';const previousDb=JSON.stringify(db);try{const {kind,record}=currentModal;const cfg=forms[kind];const formData=new FormData(e.currentTarget);const values=Object.fromEntries(formData.entries());cfg.fields.forEach(f=>{if(f[2]==='number')values[f[0]]=Number(values[f[0]]||0)});if(kind==='post'){const file=formData.get('coverFile');delete values.coverFile;values.platform='Instagram';values.cover=record?.cover||'';if(file&&file.size)values.cover=await compressImage(file);values.order=record?.order??db.posts.length}if(kind==='finance'){let existing=db.finance.find(x=>x.month===values.month);if(existing){Object.assign(existing,values)}else db.finance.push({...values,id:id()})}else if(record){Object.assign(record,values)}else{if(kind==='entry'&&values.type==='Receita')migrateLegacyMonthIncome((values.date||'').slice(0,7));db[cfg.list].push({id:id(),...values})}persist();closeForm();toast(record?'Alterações salvas':'Registro adicionado')}catch(error){console.error('Falha ao salvar registro:',error);db=JSON.parse(previousDb);if(currentModal?.record){const list=forms[currentModal.kind]?.list;currentModal.record=db[list]?.find(x=>x.id===currentModal.record.id)||db[list]?.find(x=>x.month===currentModal.record.month)||currentModal.record}render();submitButton.disabled=false;submitButton.textContent='Salvar registro →';toast('Não foi possível salvar. Confira o espaço disponível e tente novamente.')}});
document.getElementById('exportBtn').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`noza-control-backup-${monthKey()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup exportado')});
document.getElementById('importBtn').addEventListener('click',()=>document.getElementById('importFile').click());document.getElementById('importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!data||!Array.isArray(data.tasks)||!Array.isArray(data.finance))throw new Error();db={...newState(),...data};persist();toast('Backup importado com sucesso')}catch{toast('Arquivo de backup inválido')}e.target.value=''});
render();
